class Timer { /* ... */ };
Timer t1(); // Declares a function 't1' that returns a Timer!
Timer t2{}; // Creates a default-constructed Timer object.

// Case 2: Narrowing Conversions (Parentheses weakness)
int x1(5.3);  // Compiles, but truncates 5.3 to 5.
// int x2{5.3}; // Error! Braces prevent narrowing conversion.

// Case 3: Initializer List Overload (Braces feature/problem)
std::vector<int> v1(10, 20); // Creates a vector of 10 elements, value 20.
std::vector<int> v2{10, 20}; // Creates a vector with two elements: 10 and 20.
